/* QuoteMapper.findQuoteById */
SELECT QUT_SN, SVC_REQ_SN, USR_SN, QUT_AMT, QUT_CN, QUT_TTL,
       QUT_STATUS_CD, QUT_REVISE_CNT, QUT_REG_ID, QUT_UPDT_ID
  FROM QUOTE
 WHERE QUT_SN = #{qutSn}

/* QuoteMapper.findQuoteByIdForUpdate */
SELECT QUT_SN, SVC_REQ_SN, USR_SN, QUT_AMT, QUT_CN, QUT_TTL,
       QUT_STATUS_CD, QUT_REVISE_CNT, QUT_REG_ID, QUT_UPDT_ID
  FROM QUOTE
 WHERE QUT_SN = #{qutSn}
FOR UPDATE

mapper.update:
/* QuoteMapper.updateQuote */
UPDATE QUOTE
   SET QUT_AMT        = #{req.amount},
       QUT_CN         = #{req.content},
       QUT_TTL        = #{req.title},
       QUT_STATUS_CD  = 'QUTC0002',
       QUT_REVISE_CNT = QUT_REVISE_CNT + 1,
       QUT_UPDT_ID    = #{updtId}
 WHERE QUT_SN = #{qutSn}

/* QuoteMapper.withdrawQuote */
UPDATE QUOTE
   SET QUT_STATUS_CD = 'QUTC0005',
       QUT_UPDT_ID   = #{updtId}
 WHERE QUT_SN = #{qutSn}

mapper.select:
/* QuoteMapper.countMyQuotes */
SELECT COUNT(*)
  FROM QUOTE
 WHERE USR_SN = #{usrSn}

/* QuoteMapper.findAdminSummaries */ SELECT SVC_REQ_SN AS serviceRequestId, COUNT(*) AS totalQuoteCount, SUM(CASE WHEN QUT_STATUS_CD IN ('QUTC0001', 'QUTC0002') THEN 1 ELSE 0 END) AS activeQuoteCount, SUM(CASE WHEN QUT_STATUS_CD = 'QUTC0004' THEN 1 ELSE 0 END) AS selectedQuoteCount, SUM(CASE WHEN QUT_STATUS_CD NOT IN ('QUTC0001', 'QUTC0002', 'QUTC0003', 'QUTC0004', 'QUTC0005') THEN 1 ELSE 0 END) AS unsupportedQuoteCount, MAX(CASE WHEN QUT_STATUS_CD = 'QUTC0004' THEN QUT_SN END) AS selectedQuoteId, MAX(CASE WHEN QUT_STATUS_CD = 'QUTC0004' THEN USR_SN END) AS selectedProviderUserId, MAX(CASE WHEN QUT_STATUS_CD = 'QUTC0004' THEN QUT_AMT END) AS selectedAmount, MAX(CASE WHEN QUT_STATUS_CD = 'QUTC0004' THEN QUT_STATUS_CD END) AS selectedQuoteStatusCode FROM QUOTE WHERE SVC_REQ_SN IN
#{serviceRequestId}
GROUP BY SVC_REQ_SN

/* QuoteMapper.findQuoteHistory */
SELECT QUT_HST_SN, QUT_SN, QUT_HST_AMT, QUT_HST_CN, QUT_HST_REG_DT
  FROM QUOTE_HISTORY
 WHERE QUT_SN = #{qutSn}
 ORDER BY QUT_HST_REG_DT ASC

mapper.update:
/* QuoteMapper.selectQuote — 호출 전 반드시 FOR UPDATE 잠금 선행 */
UPDATE QUOTE
   SET QUT_STATUS_CD = 'QUTC0004',
       QUT_UPDT_ID   = #{updtId}
 WHERE QUT_SN = #{qutSn}

/* QuoteMapper.withdrawCompetingQuotes */
UPDATE QUOTE
   SET QUT_STATUS_CD = 'QUTC0005',
       QUT_UPDT_ID   = #{updtId}
 WHERE SVC_REQ_SN    = #{svcReqSn}
   AND QUT_SN       != #{excludeQutSn}
   AND QUT_STATUS_CD IN ('QUTC0001', 'QUTC0002')

