/* QuoteMapper.insertQuotePhoto */
INSERT INTO QUOTE_PHOTO (QUT_SN, FL_SN, SORT_NO)
VALUES (#{qutSn}, #{flSn}, #{sortNo})

mapper.select:
/* QuoteMapper.countQuoteAttachment */
SELECT COUNT(*)
  FROM QUOTE_PHOTO
 WHERE QUT_SN = #{qutSn}
   AND FL_SN = #{flSn}

/* QuoteMapper.findProviderUsrSnBySvcReqSn */
SELECT DISTINCT USR_SN
  FROM QUOTE
 WHERE SVC_REQ_SN = #{svcReqSn}
